    PaintBox1: TPaintBox;
    Timer1: TTimer;
    procedure FormCreate(Sender: TObject);
    procedure PaintBox1Paint(Sender: TObject);
    procedure Timer1Timer(Sender: TObject);
  private
    FAngle: Double;
    FPosX, FPosY: Double;
    FVelocityX, FVelocityY: Double;
    FBitmap: TBitmap;
    procedure UpdateState;
  public
    { Public declarations }
  end;

var
  Form1: TForm1;

implementation

{$R *.dfm}

procedure TForm1.FormCreate(Sender: TObject);
begin
  FAngle := 0;
  FPosX := 100;
  FPosY := 100;
  FVelocityX := 2;
  FVelocityY := 1.5;

  // Create simple image to draw (a colored rectangle for demo)
  FBitmap := TBitmap.Create;
  FBitmap.SetSize(50, 50);
  FBitmap.Canvas.Brush.Color := clRed;
  FBitmap.Canvas.FillRect(Rect(0, 0, 50, 50));

  PaintBox1.Repaint;
end;

procedure TForm1.UpdateState;
begin
  // Move position
  FPosX := FPosX + FVelocityX;
  FPosY := FPosY + FVelocityY;

  // Bounce off edges
  if (FPosX < 0) or (FPosX + FBitmap.Width > PaintBox1.Width) then
    FVelocityX := -FVelocityX;
  if (FPosY < 0) or (FPosY + FBitmap.Height > PaintBox1.Height) then
    FVelocityY := -FVelocityY;

  // Rotate
  FAngle := FAngle + 2;
  if FAngle >= 360 then
    FAngle := FAngle - 360;
end;

procedure TForm1.Timer1Timer(Sender: TObject);
begin
  UpdateState;
  PaintBox1.Repaint;
end;

procedure TForm1.PaintBox1Paint(Sender: TObject);
var
  cx, cy: Single;
  R: TRect;
  TempBitmap: TBitmap;
  AngleRad: Double;
begin
  with PaintBox1.Canvas do
  begin
    Brush.Color := clWhite;
    FillRect(PaintBox1.ClientRect);

    // Center of the image
    cx := FBitmap.Width / 2;
    cy := FBitmap.Height / 2;

    // Create temp bitmap to draw rotated image
    TempBitmap := TBitmap.Create;
    try
      TempBitmap.SetSize(FBitmap.Width, FBitmap.Height);
      TempBitmap.Canvas.Brush.Color := clFuchsia;
      TempBitmap.Canvas.FillRect(Rect(0, 0, TempBitmap.Width, TempBitmap.Height));
      TempBitmap.TransparentColor := clFuchsia;
      TempBitmap.Transparent := True;

      // Rotate manually using Canvas
      TempBitmap.Canvas.Lock;
      try
        // Slightly more advanced: rotate using affine matrix
        AngleRad := DegToRad(FAngle);

        // Copy source to temp canvas
        TempBitmap.Canvas.Draw(0, 0, FBitmap);

        // Draw rotated using "DrawRotatedBitmap" (manually)
        // Here we don't use GDI+ or FireMonkey, but simulate it crudely

        // You can improve this using TransformBitmap or D2D libraries
        BrushCopy(Bounds(Round(FPosX), Round(FPosY), FBitmap.Width, FBitmap.Height),
                  TempBitmap, Rect(0, 0, FBitmap.Width, FBitmap.Height), clFuchsia);
      finally
        TempBitmap.Canvas.Unlock;
      end;
    finally
      TempBitmap.Free;
    end;
  end;
