  Timer1.Enabled := True;
  FRotationAngle := 0.0;
  Image1.Picture.LoadFromFile('your_image.png'); // Replace with your image file
end;

procedure TForm1.Timer1Timer(Sender: TObject);
begin
  FRotationAngle := FRotationAngle + 1.0; // Adjust for rotation speed
  RotateImage;
end;

procedure TForm1.RotateImage;
var
  Bitmap: TBitmap;
  NewBitmap: TBitmap;
  Matrix: TMatrix;
begin
  Bitmap := Image1.Picture.Bitmap;
  if Bitmap = nil then Exit;

  NewBitmap := TBitmap.Create;
  try
    NewBitmap.Width := Bitmap.Width;
    NewBitmap.Height := Bitmap.Height;
    NewBitmap.Canvas.SetFont(Image1.Font); // Preserve font if any

    Matrix := TMatrix.Identity;
    Matrix.Rotate(FRotationAngle * (PI / 180.0)); // Convert degrees to radians
    Matrix.Translate(Bitmap.Width / 2, Bitmap.Height / 2);
    Matrix.Rotate(-FRotationAngle * (PI / 180.0)); // Undo translation rotation
    Matrix.Translate(-Bitmap.Width / 2, -Bitmap.Height / 2);

    NewBitmap.Canvas.Bitmap.StretchDraw(Rect(0, 0, Bitmap.Width, Bitmap.Height), Bitmap, Matrix);

    Image1.Picture.Bitmap := NewBitmap.Bitmap;
  finally
    NewBitmap.Free;
  end;
end;

procedure TForm1.Image1MouseDown(Sender: TObject; Button: TMouseButton);
begin
  FDragging := True;
  FDragStartX := Mouse.X;
  FDragStartY := Mouse.Y;
end;

procedure TForm1.Image1MouseMove(Sender: TObject; Shift: TShiftState; X, Y: Integer);
var
