```java
import org.springframework.boot.actuate.health.Health;
import org.springframework.boot.actuate.health.HealthAggregator;
import org.springframework.boot.actuate.health.HealthIndicator;
import org.springframework.boot.actuate.health.Status;
import java.util.Map;
import java.util.stream.Collectors;

public class PgWHealthAggregator implements HealthAggregator {

    @Override
    public Health aggregate(Map<String, Health> healths) {
        boolean atLeastOneUp = healths.values().stream()
                .anyMatch(health -> health.getStatus() == Status.UP);

        Status status = atLeastOneUp ? Status.UP : Status.DOWN;

        return Health.status(status)
                .details(healths.entrySet().stream()
                        .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue)))
                .build();
    }
}
