use bevy::prelude::*;
use bevy::render::view::Camera;
use bevy::window::PrimaryWindow;
use image::io::png::PngEncoder;
use image::ColorType;
use std::fs::File;
use std::path::Path;

// Configuration
const NUM_ANGLES: usize = 36;
const OUTPUT_DIR: &str = "screenshots";

#[derive(Resource)]
struct ModelData {
    mesh: Handle<Mesh>,
    material: Handle<StandardMaterial>,
}

fn main() {
    App::new()
        .add_plugins(DefaultPlugins)
        .insert_resource(ModelData {
            mesh: Handle::default(),
            material: Handle::default(),
        })
        .add_systems(Startup, load_model)
        .add_systems(Startup, create_output_dir)
        .add_systems(Startup, take_screenshots)
        .run();
}

fn load_model(
    mut commands: Commands,
    asset_server: Res<AssetServer>,
) {
    // Replace "path/to/your/model.glb" with the actual path to your model file.
    // Supported formats: glTF, OBJ, etc.
    let model_path = "path/to/your/model.glb";

    let model = asset_server.load(model_path);

    // Check if the model loaded successfully
    if model.is_none() {
        println!("Failed to load model from: {}", model_path);
        return;
    }

    commands.insert_resource(ModelData {
        mesh: model.clone(),
        material: asset_server.load("path/to/your/material.png"), // Optional: Load a texture
    });
}

fn create_output_dir() {
    std::fs::create_dir_all(OUTPUT_DIR).expect("Failed to create output directory");
}

fn take_screenshots(
    mut commands: Commands,
    model_data: Res<ModelData>,
    primary_window_query: Query<&Window, With<PrimaryWindow>>,
    camera_query: Query<&Camera>,
) {
    let window = primary_window_query.single();
    let width = window.width() as u32;
    let height = window.height() as u32;

    for i in 0..NUM_ANGLES {
        let angle = (i as f32 / NUM_ANGLES as f32) * 360.0;

        // Create a new camera for each angle
        commands.spawn(Camera::new(Camera3d {
            transform: Transform::from_rotation(Quat::from_axis_angle(Vec3::Y, angle.to_radians()))
                .with_translation(Vec3::new(0.0, 0.0, 5.0)), // Adjust distance as needed
            ..default()
        }));

        // Take screenshot
        let image = bevy::render::render_resource::RenderTexture::new(
            &mut commands,
            width,
            height,
            ColorType::Rgba8,
            false,
        );

        let mut frame_reader = commands.get_entity(commands.get_entities(Query::any()).id()).unwrap();

        let image_buffer = bevy::render::render_resource::RenderTexture::read_to_image(
            &mut commands,
            &image,
        ).unwrap();

        let path = Path::new(OUTPUT_DIR).join(format!("screenshot_{:03}.png", i));
        let file = File::create(path).expect("Failed to create file");
        let encoder = PngEncoder::new(file);
        encoder.encode(&image_buffer, width, height, ColorType::Rgba8).expect("Failed to encode image");

        println!("Screenshot saved to: {:?}", path);

        // Remove the camera after taking the screenshot
        commands.despawn(frame_reader);
    }
}
```

