        {
            Text = text,
            Foreground = (Brush)FindResource("OnSurfaceBrush"),
            FontSize = 16,
            TextWrapping = TextWrapping.Wrap,
            Style = (Style)FindResource("ParagraphBaseRegular")
        };

        // Add the TextBlock to the Border
        newBorder.Child = newTextBlock;

        // Add the Border to the StackPanel
        MyStackPanel.Children.Add(newBorder); // Replace MyStackPanel with the actual name of your StackPanel
    }

    // Example usage (e.g., in a button click event)
    private void Button_Click(object sender, RoutedEventArgs e)
    {
