console.log(`The ISO week number for ${date2} is: ${weekNumber2}`);

const date3 = new Date(2023, 11, 31); // December 31, 2023
const weekNumber3 = isoWeekNumber(date3);
console.log(`The ISO week number for ${date3} is: ${weekNumber3}`);
```

